// What counts as a legal or similarly significant effect. Art. 22(1) only bites when a decision is
// BOTH solely automated AND produces legal effects or similarly significantly affects the person.
// Recital 71 and the WP29 guidelines on automated decision-making (WP251 rev.01) give the examples:
// refusal of credit, e-recruiting without human intervention, and effects on access to services.
// weight legal means the effect is a legal one; weight significant means similarly significant.
const rows = [
  ['credit_or_lending', 'Credit, lending or insurance outcome', 'Granting, refusing or pricing credit, a loan, a mortgage or an insurance policy.', 'credit|loan|mortgage|lending|overdraft|insurance|premium|underwrit|creditworth', 'affects_credit', 'legal'],
  ['employment', 'Hiring, promotion or dismissal', 'Screening out an applicant, rejecting a candidate, or a decision about promotion, discipline or dismissal.', 'applicant|candidate|cv |resume|shortlist|hiring|recruit|promotion|dismiss|termination|probation', 'affects_employment', 'legal'],
  ['access_to_service', 'Access to a service or a contract', 'Refusing, suspending or ending access to a service, an account or a contract.', 'suspend|ban|blocked|closed the account|refuse service|deny access|terminate the contract|deregister|delist', 'affects_service', 'significant'],
  ['pricing_or_terms', 'The price or the terms someone is offered', 'Personalised pricing, a different deposit, a worse tariff or different contract terms for this person.', 'personalised pric|personalized pric|dynamic pric|surge|deposit|tariff|different terms|price for this customer', 'affects_pricing', 'significant'],
  ['benefit_or_entitlement', 'A benefit, allowance or entitlement', 'Granting or refusing a benefit, an allowance, a subsidy, a place or an entitlement.', 'benefit|allowance|subsid|entitlement|welfare|grant application|eligibility|place on the course', 'affects_benefit', 'legal'],
  ['legal_or_enforcement', 'A legal or enforcement outcome', 'A fine, a penalty, a fraud determination, a report to an authority or anything with a direct legal consequence.', 'fine|penalty|fraud|sanction|enforcement|reported to|prosecut|legal action|debt recovery', 'affects_legal', 'legal'],
  ['health_or_care', 'Health or care', 'Triage, eligibility for treatment, care level or anything affecting the care a person receives.', 'triage|treatment|diagnos|care level|clinical|prescrib|waiting list|referral', 'affects_health', 'significant'],
  ['education_or_grading', 'Education, grading or assessment', 'Automatic grading, admission, streaming or exclusion in education or training.', 'grade|grading|exam|admission|enrol|enroll|streaming|expel|exclusion|assessment score', 'affects_education', 'significant']
];
return rows.map(r => ({ json: { effect_key: r[0], title: r[1], description: r[2], keywords: r[3], form_field: r[4], weight: r[5] } }));

const form = $('Log A Decision').first().json;
const policy = $('Set Article 22 Policy').first().json;
const rules = $input.all().map(i => i.json).filter(r => r && r.effect_key);
const minChars = Number(policy.min_description_chars) || 40;
const validBases = String(policy.valid_bases || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);

const text = [form.decision_text, form.inputs_used, form.consequence].map(v => String(v || '')).join(' \n ');
const lower = text.toLowerCase();
const yes = v => String(v || '').trim().toLowerCase() === 'yes';
const unsure = v => String(v || '').trim().toLowerCase() === 'not sure';

const met = [];
const unsureKeys = [];
for (const r of rules) {
  const sources = [];
  const field = String(r.form_field || '');
  if (field && yes(form[field])) sources.push({ source: 'form', evidence: field + ' = Yes' });
  else if (field && unsure(form[field])) unsureKeys.push(r.effect_key);
  const kws = String(r.keywords || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);
  const hit = kws.find(k => k && lower.includes(k));
  if (hit) sources.push({ source: 'keyword', evidence: 'the decision text contains "' + hit + '"' });
  if (sources.length) met.push({ effect_key: r.effect_key, title: r.title, weight: r.weight || 'significant',
                                 source: sources.map(s => s.source).join('+'), evidence: sources.map(s => s.evidence).join('; ') });
}

// Art. 22(1) has two limbs and BOTH must hold. human_involved describes the first.
const humanRaw = String(form.human_involved || '').trim().toLowerCase();
const solelyAutomated = humanRaw === 'no human involved';
const rubberStamp = humanRaw === 'a person signs it off without reviewing';
const realHuman = humanRaw === 'a person reviews it and can change it';
const basis = String(form.lawful_basis || '').trim().toLowerCase();
const basisValid = validBases.includes(basis);

const rulesList = rules.map(r => r.effect_key + ': ' + r.title + ' (' + r.description + ')').join('\n');
const judgePrompt = 'EFFECTS:\n' + rulesList + '\n\nALREADY MET (do not repeat): ' + (met.map(m => m.effect_key).join(', ') || 'none') +
  '\n\nDECISION:\n' + text +
  '\n\nList any effect the decision shows but which is not already met. For each give the effect_key and a verbatim quote, at least four words, copied exactly from the DECISION. If nothing more is shown, return an empty list.';

return [{ json: {
  decision_ref: String(form.decision_ref || '').trim() || ('AUTO-' + String($execution.id)),
  logged_at: new Date().toISOString(),
  system_name: String(form.system_name || ''),
  subject_ref: String(form.subject_ref || ''),
  decision_text: String(form.decision_text || ''),
  text,
  human_involved: String(form.human_involved || ''),
  solely_automated: solelyAutomated, rubber_stamp: rubberStamp, real_human: realHuman,
  lawful_basis: String(form.lawful_basis || ''), basis_valid: basisValid, valid_bases: validBases,
  rules_loaded: rules.length,
  effect_keys: rules.map(r => r.effect_key),
  effect_titles: Object.fromEntries(rules.map(r => [r.effect_key, r.title])),
  effect_weights: Object.fromEntries(rules.map(r => [r.effect_key, r.weight || 'significant'])),
  met, unsure_keys: unsureKeys,
  description_too_short: String(form.decision_text || '').trim().length < minChars,
  min_description_chars: minChars,
  judge_prompt: judgePrompt
} }];

const s = $('Classify The Decision').first().json;
const item = $input.first().json || {};
const out = item.output && typeof item.output === 'object' ? item.output : null;
const added = [];
const rejected = [];
let judgeStatus, judgeNote = '';
if (out && Array.isArray(out.additional_effects)) {
  judgeStatus = 'answered';
  judgeNote = String(out.note || '');
  const lower = String(s.text || '').toLowerCase();
  for (const a of out.additional_effects) {
    const key = String((a && a.effect_key) || '').trim();
    const quote = String((a && a.quote) || '').trim();
    if (!s.effect_keys.includes(key)) { rejected.push(key + ': unknown effect'); continue; }
    if (s.met.some(m => m.effect_key === key) || added.some(m => m.effect_key === key)) { rejected.push(key + ': already met'); continue; }
    if (quote.length < 12 || !lower.includes(quote.toLowerCase())) { rejected.push(key + ': quote not found in the decision'); continue; }
    added.push({ effect_key: key, title: s.effect_titles[key] || key, weight: s.effect_weights[key] || 'significant',
                 source: 'judge', evidence: 'quoted from the decision: "' + quote.slice(0, 200) + '"' });
  }
} else {
  judgeStatus = 'did not answer';
  judgeNote = 'the reviewer did not answer' + (item.error ? ': ' + String(item.error.message || item.error).slice(0, 160) : '');
}

const all = s.met.concat(added);
// A sign-off that never changes anything is not human intervention: WP251 says the reviewer must have
// authority and competence to change the decision. So rubber_stamp is treated as solely automated.
const solely = s.solely_automated || s.rubber_stamp;

let verdict, reason;
if (!s.rules_loaded) {
  verdict = 'INCOMPLETE';
  reason = 'the art22_effect_rules table is empty, so no effect could be tested; run Set Up Tables first. An empty table is not a finding that Art. 22 does not apply';
} else if (s.description_too_short) {
  verdict = 'INCOMPLETE';
  reason = 'the decision text is shorter than ' + s.min_description_chars + ' characters, which is too little to classify';
} else if (!all.length) {
  verdict = 'NO_SIGNIFICANT_EFFECT';
  reason = 'no legal or similarly significant effect was found, so Art. 22(1) is not engaged on this record. That is a statement about what was written here, not a guarantee about the system';
} else if (!solely) {
  verdict = 'NOT_SOLELY_AUTOMATED';
  reason = all.length + ' effect(s) found, but a person reviews the decision and can change it, so Art. 22(1) does not bite. Keep the evidence that the review is real';
} else if (!s.basis_valid) {
  verdict = 'ART22_NO_LAWFUL_BASIS';
  reason = 'the decision is solely automated and has ' + all.length + ' significant effect(s), and the recorded basis "' + (s.lawful_basis || 'none') + '" is not one of the three Art. 22(2) exceptions (contract, law, explicit consent). On this record the decision should not be made this way';
} else {
  verdict = 'ART22_SAFEGUARDS_REQUIRED';
  reason = 'the decision is solely automated with ' + all.length + ' significant effect(s) under the Art. 22(2) exception "' + s.lawful_basis + '", so Art. 22(3) requires human intervention, the right to express a point of view and the right to contest';
}

const needsAction = verdict === 'ART22_SAFEGUARDS_REQUIRED' || verdict === 'ART22_NO_LAWFUL_BASIS';
const lines = all.map(m => '- [' + m.weight + '] ' + m.title + ' [' + m.source + ']: ' + m.evidence);
lines.push('- Human involvement recorded as: ' + (s.human_involved || 'not stated') + (s.rubber_stamp ? ' (a sign-off that cannot change the outcome counts as solely automated)' : ''));
if (s.unsure_keys.length) lines.push('- Answered "Not sure": ' + s.unsure_keys.join(', ') + ' (not counted; a person has to decide)');
if (rejected.length) lines.push('- Reviewer suggestions not counted: ' + rejected.join('; '));
lines.push('- Reviewer: ' + judgeStatus + (judgeNote ? ' (' + judgeNote.slice(0, 200) + ')' : ''));
const report = 'Verdict ' + verdict + ': ' + reason + '\n' + lines.join('\n');

return [{ json: Object.assign({}, s, {
  effects_all: all,
  effect_count: all.length,
  effects_met_text: all.map(m => m.effect_key).join(', ') || 'none',
  judge_added_text: added.map(m => m.effect_key).join(', ') || 'none',
  judge_status: judgeStatus, judge_note: judgeNote,
  verdict, verdict_reason: reason, needs_action: needsAction, report
}) }];

const d = $('Decide On Article 22').first().json;
const rows = d.effects_all.map(m => ({ json: {
  decision_ref: d.decision_ref, system_name: d.system_name, effect_key: m.effect_key,
  source: m.source, evidence: String(m.evidence).slice(0, 400), found_at: d.logged_at } }));
if (!rows.length) rows.push({ json: {
  decision_ref: d.decision_ref, system_name: d.system_name, effect_key: 'none',
  source: 'rules', evidence: 'no significant effect found; verdict ' + d.verdict, found_at: d.logged_at } });
return rows;

const form = $('Ask For Human Review').first().json;
const policy = $('Set Review Policy').first().json;
const days = Number(policy.response_days) || 30;
const wanted = String(form.decision_ref || '').trim();
const rows = $input.all().map(i => i.json).filter(r => r && r.decision_ref);
const hit = rows.find(r => String(r.decision_ref).trim() === wanted);

const now = new Date();
const deadline = new Date(now.getTime() + days * 86400 * 1000);

let lookupState, state, note;
if (!wanted) {
  lookupState = 'no reference given';
  state = 'INCOMPLETE';
  note = 'no decision reference was given, so the request could not be matched to a decision. It is still recorded, and a person has to find the decision by hand. This is not a finding that no such decision exists';
} else if (!rows.length) {
  lookupState = 'register empty';
  state = 'INCOMPLETE';
  note = 'the art22_decisions register holds no rows at all, so the reference could not be checked. An empty register is not evidence that the decision was never made';
} else if (!hit) {
  lookupState = 'not found';
  state = 'INCOMPLETE';
  note = 'reference "' + wanted + '" is not in the register of ' + rows.length + ' decision(s). The request stands and a person has to find the decision; a missing row is not a reason to close it';
} else {
  lookupState = 'found';
  state = 'OPEN';
  note = 'matched decision "' + wanted + '" from ' + String(hit.system_name || 'an unnamed system') + ', logged verdict ' + String(hit.verdict || 'unknown');
}

const typeRaw = String(form.request_type || '').trim();
const summary = 'Request: ' + (typeRaw || 'not stated') + '\nDecision: ' + (wanted || 'none given') +
  '\nLookup: ' + lookupState + '\nAnswer due by ' + deadline.toISOString().slice(0, 10) +
  ' (Art. 12(3) is one month, extendable by two more where the request is complex)\n' + note;

return [{ json: {
  review_id: String($execution.id),
  requested_at: now.toISOString(),
  decision_ref: wanted,
  requested_by: String(form.requested_by || ''),
  request_type: typeRaw,
  grounds: String(form.grounds || '').slice(0, 900),
  deadline_at: deadline.toISOString(),
  response_days: days,
  lookup_state: lookupState,
  state, note, summary,
  matched_system: hit ? String(hit.system_name || '') : '',
  matched_verdict: hit ? String(hit.verdict || '') : '',
  register_rows: rows.length
} }];

const policy = $('Set Digest Policy').first().json;
const decisions = $('Read The Decisions').all().map(i => i.json).filter(r => r && r.decision_ref);
const reviews = $input.all().map(i => i.json).filter(r => r && r.review_id);
const now = Date.now();

const unsafeguarded = decisions.filter(d =>
  (String(d.verdict) === 'ART22_SAFEGUARDS_REQUIRED' || String(d.verdict) === 'ART22_NO_LAWFUL_BASIS') &&
  String(d.safeguards_documented || 'no').toLowerCase() !== 'yes');
const noBasis = decisions.filter(d => String(d.verdict) === 'ART22_NO_LAWFUL_BASIS');

const openReviews = reviews.filter(r => String(r.state || '').toUpperCase() !== 'CLOSED');
const late = [];
const soon = [];
for (const r of openReviews) {
  const dl = new Date(String(r.deadline_at || ''));
  if (isNaN(dl.getTime())) { late.push({ review_id: r.review_id, decision_ref: r.decision_ref, days_left: 0, why: 'no readable deadline' }); continue; }
  const daysLeft = Math.round(((dl.getTime() - now) / 86400000) * 10) / 10;
  if (daysLeft < 0) late.push({ review_id: r.review_id, decision_ref: r.decision_ref, days_left: daysLeft, why: 'past the Art. 12(3) deadline' });
  else if (daysLeft <= Number(policy.warn_days_left || 7)) soon.push({ review_id: r.review_id, decision_ref: r.decision_ref, days_left: daysLeft, why: 'due soon' });
}
const unmatched = openReviews.filter(r => String(r.lookup_state || '') !== 'found');

const parts = [];
if (unsafeguarded.length) parts.push(unsafeguarded.length + ' decision(s) where Art. 22 applies and safeguards_documented is not yes: ' + unsafeguarded.slice(0, 10).map(d => d.decision_ref + ' (' + d.system_name + ')').join(', '));
if (noBasis.length) parts.push(noBasis.length + ' of those record no valid Art. 22(2) basis at all');
if (late.length) parts.push(late.length + ' review request(s) past the one month deadline: ' + late.slice(0, 10).map(r => r.decision_ref || r.review_id).join(', '));
if (soon.length) parts.push(soon.length + ' review request(s) due within ' + Number(policy.warn_days_left || 7) + ' days');
if (unmatched.length) parts.push(unmatched.length + ' open request(s) could not be matched to a decision and need a person to look');

const nothing = parts.length === 0;
const summary = nothing
  ? (decisions.length || reviews.length
      ? 'Nothing outstanding: ' + decisions.length + ' decision(s) and ' + openReviews.length + ' open request(s), none missing safeguards and none past its deadline.'
      : 'The register and the request table are both empty. That means nothing was logged, which is not the same as no automated decisions being made.')
  : parts.join('\n');

return [{ json: {
  checked_at: new Date().toISOString(),
  decisions_read: decisions.length, reviews_read: reviews.length, open_reviews: openReviews.length,
  unsafeguarded: unsafeguarded.length, no_basis: noBasis.length,
  late: late.length, due_soon: soon.length, unmatched: unmatched.length,
  needs_attention: !nothing, summary
} }];
